/**
 * Time_Widget.jsx
 * Draggable, resizable time widget inspired by splash_screen.html
 * Displays current time for various locations with beautiful animations
 */

import React, { useState, useEffect, useRef } from 'react';
import './Time_Widget.css';

const TimeWidget = ({ isOpen, onClose, location = 'local' }) => {
    const [currentTime, setCurrentTime] = useState(new Date());
    const [displayLocation, setDisplayLocation] = useState(location);
    const [position, setPosition] = useState({ x: 100, y: 100 });
    const [size, setSize] = useState({ width: 320, height: 400 });
    const [isDragging, setIsDragging] = useState(false);
    const [isResizing, setIsResizing] = useState(false);
    const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });

    const widgetRef = useRef(null);
    const resizeStartRef = useRef({ x: 0, y: 0, width: 0, height: 0 });

    // Update time every second
    useEffect(() => {
        const timer = setInterval(() => {
            setCurrentTime(new Date());
        }, 1000);

        return () => clearInterval(timer);
    }, []);

    // Format time
    const formatTime = (date) => {
        return date.toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: true
        });
    };

    // Format date
    const formatDate = (date) => {
        return date.toLocaleDateString('en-US', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    };

    // Dragging handlers
    const handleMouseDown = (e) => {
        if (e.target.closest('.widget-controls') || e.target.closest('.resize-handle')) {
            return;
        }

        setIsDragging(true);
        setDragOffset({
            x: e.clientX - position.x,
            y: e.clientY - position.y
        });
    };

    const handleMouseMove = (e) => {
        if (isDragging) {
            setPosition({
                x: e.clientX - dragOffset.x,
                y: e.clientY - dragOffset.y
            });
        } else if (isResizing) {
            const deltaX = e.clientX - resizeStartRef.current.x;
            const deltaY = e.clientY - resizeStartRef.current.y;

            setSize({
                width: Math.max(280, resizeStartRef.current.width + deltaX),
                height: Math.max(350, resizeStartRef.current.height + deltaY)
            });
        }
    };

    const handleMouseUp = () => {
        setIsDragging(false);
        setIsResizing(false);
    };

    // Resize handler
    const handleResizeMouseDown = (e) => {
        e.stopPropagation();
        setIsResizing(true);
        resizeStartRef.current = {
            x: e.clientX,
            y: e.clientY,
            width: size.width,
            height: size.height
        };
    };

    // Attach global mouse handlers
    useEffect(() => {
        if (isDragging || isResizing) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
            return () => {
                window.removeEventListener('mousemove', handleMouseMove);
                window.removeEventListener('mouseup', handleMouseUp);
            };
        }
    }, [isDragging, isResizing, dragOffset, position]);

    // Size control handlers
    const increaseSize = () => {
        setSize(prev => ({
            width: prev.width + 40,
            height: prev.height + 50
        }));
    };

    const decreaseSize = () => {
        setSize(prev => ({
            width: Math.max(280, prev.width - 40),
            height: Math.max(350, prev.height - 50)
        }));
    };

    if (!isOpen) return null;

    return (
        <div
            ref={widgetRef}
            className={`time-widget widget-draggable ${isDragging ? 'widget-dragging' : ''}`}
            style={{
                left: `${position.x}px`,
                top: `${position.y}px`,
                width: `${size.width}px`,
                height: `${size.height}px`
            }}
            onMouseDown={handleMouseDown}
        >
            {/* Corner decorations */}
            <div className="corner-top-right"></div>
            <div className="corner-bottom-left"></div>

            {/* Widget controls */}
            <div className="widget-controls">
                <div className="widget-control-btn" onClick={increaseSize} title="Make Bigger">
                    ⧨
                </div>
                <div className="widget-control-btn" onClick={decreaseSize} title="Make Smaller">
                    ⧩
                </div>
                <div className="widget-control-btn" onClick={onClose} title="Close">
                    ⧬
                </div>
            </div>

            {/* Resize handle */}
            <div className="resize-handle" onMouseDown={handleResizeMouseDown}></div>

            {/* Widget label */}
            <div className="time-widget-label">TIME</div>

            {/* Main time display */}
            <div className="time-main-display">
                <div className="time-digital">
                    {formatTime(currentTime)}
                </div>
                <div className="time-date">
                    {formatDate(currentTime)}
                </div>
            </div>

            {/* Time details */}
            <div className="time-details">
                <div className="time-detail-item">
                    <div className="time-detail-label">Hour</div>
                    <div className="time-detail-value">{currentTime.getHours()}</div>
                </div>
                <div className="time-detail-item">
                    <div className="time-detail-label">Minute</div>
                    <div className="time-detail-value">{currentTime.getMinutes()}</div>
                </div>
                <div className="time-detail-item">
                    <div className="time-detail-label">Second</div>
                    <div className="time-detail-value">{currentTime.getSeconds()}</div>
                </div>
            </div>

            {/* Location display */}
            <div className="time-location">
                {displayLocation === 'local' ? 'Local Time' : displayLocation}
            </div>

            {/* Animated background effect */}
            <div className="time-glow-effect"></div>
        </div>
    );
};

export default TimeWidget;
